#include <bits/stdc++.h>
using namespace std; struct P{int x,y;}; struct M{int l,i,j;};
bool col(P a,P b,P c){return 1LL*(b.x-a.x)*(c.y-a.y)==1LL*(b.y-a.y)*(c.x-a.x);}
string enc(vector<int>r,vector<int>b){string s;for(int x:r)s.push_back(char(x));for(int x:b)s.push_back(char(x));return s;}
M parse(string s){auto c=s.find(':');auto q=s.find(',');return {s[0]=='b',stoi(s.substr(c+1,q-c-1))-1,stoi(s.substr(q+1))-1};}
bool legal(string const&s,M m){int o=30*m.l,q=30*(1-m.l);return (unsigned char)s[o+m.j]!=(unsigned char)s[q+m.i]&&(unsigned char)s[o+m.i]!=(unsigned char)s[q+m.j];}
string apply(string s,M m){swap(s[30*m.l+m.i],s[30*m.l+m.j]);return s;}
int pot(string const&s){P p[60];for(int i=0;i<30;i++){p[2*i]={i+1,(unsigned char)s[i]};p[2*i+1]={i+1,(unsigned char)s[30+i]};}int v=0;for(int i=0;i<60;i++)for(int j=i+1;j<60;j++)for(int k=j+1;k<60;k++)v+=col(p[i],p[j],p[k]);return v;}
int A(vector<P>const&T,P p){int a[60],n=0;for(auto u:T){int x=u.x-p.x,y=u.y-p.y,g=gcd(abs(x),abs(y));x/=g;y/=g;if(x<0||(x==0&&y<0))x=-x,y=-y;a[n++]=(x+30)*61+y+30;}sort(a,a+n);int z=0;for(int i=0;i<n;){int j=i+1;while(j<n&&a[j]==a[i])j++;int c=j-i;z+=c*(c-1)/2;i=j;}return z;}
int B(vector<P>const&T,P p,P q){int z=0;for(auto u:T)z+=col(p,q,u);return z;}
int npot(string const&s,int cur,M m){int o=30*m.l;P a={m.i+1,(unsigned char)s[o+m.i]},b={m.j+1,(unsigned char)s[o+m.j]},c={m.i+1,b.y},d={m.j+1,a.y};vector<P>T;for(int l=0;l<2;l++)for(int i=0;i<30;i++)if(!(l==m.l&&(i==m.i||i==m.j)))T.push_back({i+1,(unsigned char)s[30*l+i]});return cur+A(T,c)+A(T,d)+B(T,c,d)-A(T,a)-A(T,b)-B(T,a,b);}
vector<M> allm(){vector<M>v;for(int l=0;l<2;l++)for(int i=0;i<30;i++)for(int j=i+1;j<30;j++)v.push_back({l,i,j});return v;}
int main(){vector<int>r={19,15,26,18,23,17,8,2,25,13,9,4,20,28,1,12,7,24,29,5,3,30,27,11,14,6,21,16,22,10},b={12,10,23,9,7,15,26,6,21,1,20,2,8,29,30,16,27,25,3,11,14,18,4,5,22,28,24,13,17,19};vector<string> w={"b:1,11","r:1,16","b:2,26","b:2,8","b:2,23","r:1,16","r:3,21","r:2,30","b:2,6","r:3,21","b:1,11","r:1,18","r:6,30","r:1,30","r:2,30","b:11,23","b:6,18","b:18,23","b:18,27","b:7,23","b:23,27","b:19,27","b:11,23","b:11,27","b:18,27","r:3,21","r:2,3","b:18,27","r:3,27","b:9,27","b:2,9","r:5,14","b:2,6","r:2,3","r:3,27","r:2,30","r:9,30","b:2,9","r:2,30","b:1,6","r:3,27","r:5,9","r:5,23","r:3,27","r:5,14","r:19,27","r:3,14","r:3,23","r:23,27","r:14,27","b:6,29","r:5,14","r:5,23","b:6,29","r:3,9","b:14,19","r:5,14","b:8,14","r:3,8","b:3,14","b:8,12","r:3,23","r:3,5","r:5,14","b:3,9","b:1,3","b:1,6","b:2,9","b:2,26"};vector<int> e={6,7,7,9,9,8,8,8,10,9,8,9,10,10,8,7,8,10,9,8,7,8,9,9,8,9,10,9,9,9,9,9,10,8,9,8,9,10,10,9,9,9,9,9,9,8,8,9,8,9,7,8,8,9,7,7,9,7,8,8,9,8,9,9,8,8,8,7,7,5};string s=enc(r,b);assert(pot(s)==6&&e.size()==w.size()+1&&e[0]==6);for(size_t i=0;i<w.size();i++){M m=parse(w[i]);assert(legal(s,m));int p=npot(s,e[i],m);s=apply(s,m);assert(p==e[i+1]&&pot(s)==p);}assert(pot(s)==5);string st=enc(r,b);auto mv=allm();unordered_set<string>seen;queue<pair<string,int>>q;seen.insert(st);q.push({st,6});bool lower=false;while(!q.empty()){auto [u,p]=q.front();q.pop();for(auto m:mv){if(!legal(u,m))continue;int z=npot(u,p,m);if(z>9)continue;string v=apply(u,m);if(!seen.insert(v).second)continue;if(z<6)lower=true;q.push({move(v),z});}}assert(seen.size()==860&&!lower);cout<<"AC p31 recovered tail audit\n"<<"moves: 69\nbarrier: 10\nlower_component_9: 860\nfinal_potential: 5\n";}
